import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2022","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2022.md","filePath":"aireblock-releases/AireForms/aireforms-2022.md","lastUpdated":1786565768000}`),a={name:`aireblock-releases/AireForms/aireforms-2022.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2022" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2022</span> <a class="header-anchor" href="#aireforms-release-notes-—-2022" aria-label="Permalink to “AireForms Release Notes — 2022”">​</a></h1><p>This page contains the AireForms releases published during 2022.</p><h2 id="version-5-18-0-—-welsh-translations-designer-fixes" tabindex="-1">Version 5.18.0 — Welsh Translations &amp; Designer Fixes <a class="header-anchor" href="#version-5-18-0-—-welsh-translations-designer-fixes" aria-label="Permalink to “Version 5.18.0 — Welsh Translations &amp; Designer Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 12, 2022</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added basic Welsh translations for the framework</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved display issues with highlighted sections when the section contains no label</li><li>Fixed an issue in the new designer where checkbox choice values were not being automatically generated</li><li>Fixed an issue where marking or unmarking a reference data item as exclusive was not saved</li><li>Fixed an issue where a combination of custom and non-custom alert messages could generate an invalid building block</li></ul><h2 id="version-5-17-0-—-image-compression" tabindex="-1">Version 5.17.0 — Image Compression <a class="header-anchor" href="#version-5-17-0-—-image-compression" aria-label="Permalink to “Version 5.17.0 — Image Compression”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 24, 2022</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Images uploaded through forms and the new designer are now automatically compressed to better handle large images</li></ul><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Reduced storage requirements for annotated images</li></ul><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the Date control displayed the incorrect date in its hint for users in a negative UTC timezone</li><li>Fixed an issue where static images were not being rehydrated in the new designer</li><li>Fixed an issue where the default alert checkbox for constraints was not correctly rehydrated in the new designer</li><li>Fixed an issue where removing a help message from a control could leave an empty help message in the runtime</li><li>Fixed XPath validation in the new designer when using casts</li></ul><h2 id="version-5-16-0-—-designer-accessibility-improvements" tabindex="-1">Version 5.16.0 — Designer &amp; Accessibility Improvements <a class="header-anchor" href="#version-5-16-0-—-designer-accessibility-improvements" aria-label="Permalink to “Version 5.16.0 — Designer &amp; Accessibility Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 11, 2022</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Various improvements to the new building block designer</li><li>Further accessibility improvements to forms</li></ul><h2 id="version-5-15-1-—-explanatory-text-links" tabindex="-1">Version 5.15.1 — Explanatory Text Links <a class="header-anchor" href="#version-5-15-1-—-explanatory-text-links" aria-label="Permalink to “Version 5.15.1 — Explanatory Text Links”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 29, 2022</p></blockquote><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where links in explanatory text and other form controls were not opening in a new tab</li></ul><h2 id="version-5-15-0-—-new-building-block-designer" tabindex="-1">Version 5.15.0 — New Building Block Designer <a class="header-anchor" href="#version-5-15-0-—-new-building-block-designer" aria-label="Permalink to “Version 5.15.0 — New Building Block Designer”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 7, 2022</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Released the new building block designer</li><li>The legacy Orbeon designer remains available through the <strong>Legacy Designer</strong> option</li><li>Added the ability to refresh available building blocks while designing a form</li><li>Added paging support to the Patient Forms API</li><li>Added filtering by <code>correlationId</code> to the Patient Forms API</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved form accessibility</li></ul><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where V1 form-based extracts using maximum results could return more results than expected</li></ul><h2 id="version-5-14-0-—-correlation-id-pre-population" tabindex="-1">Version 5.14.0 — Correlation ID Pre-Population <a class="header-anchor" href="#version-5-14-0-—-correlation-id-pre-population" aria-label="Permalink to “Version 5.14.0 — Correlation ID Pre-Population”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 5, 2022</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for pre-population based on <code>correlationId</code></li><li>When enabled, pre-population only uses existing data saved against the supplied correlation ID</li><li>Added the ability to export and import building block definitions from the building block list</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Reference data items can now be marked as exclusive or configured with a stop condition from the reference data page</li></ul><h2 id="version-5-13-0-—-reference-data-improvements" tabindex="-1">Version 5.13.0 — Reference Data Improvements <a class="header-anchor" href="#version-5-13-0-—-reference-data-improvements" aria-label="Permalink to “Version 5.13.0 — Reference Data Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 22, 2022</p></blockquote><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added support for sending the form title to the notification plugin</li><li>New reference data items now suggest a default value based on the entered label</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where reference data allowed a whitespace-only label</li></ul><h2 id="version-5-12-1-—-building-block-relevance-fix" tabindex="-1">Version 5.12.1 — Building Block Relevance Fix <a class="header-anchor" href="#version-5-12-1-—-building-block-relevance-fix" aria-label="Permalink to “Version 5.12.1 — Building Block Relevance Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 27, 2022</p></blockquote><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue when changing a building block relevance rule from custom back to always display in the form designer</li></ul><h2 id="version-5-12-0-—-designer-pdf-improvements" tabindex="-1">Version 5.12.0 — Designer &amp; PDF Improvements <a class="header-anchor" href="#version-5-12-0-—-designer-pdf-improvements" aria-label="Permalink to “Version 5.12.0 — Designer &amp; PDF Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 24, 2022</p></blockquote><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Increased the available heading space in generated PDFs</li></ul><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed form designer validation when using an instance-based XPath such as <code>instance(&#39;bb-a&#39;)/$control</code></li><li>Fixed an issue where new rows could not be added to itemsets in Orbeon</li></ul><h2 id="version-5-11-0-—-google-sheets-delivery" tabindex="-1">Version 5.11.0 — Google Sheets Delivery <a class="header-anchor" href="#version-5-11-0-—-google-sheets-delivery" aria-label="Permalink to “Version 5.11.0 — Google Sheets Delivery”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 8, 2022</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a Google Sheets Single Pass delivery channel</li></ul><h2 id="version-5-10-2-—-airetoken-fix" tabindex="-1">Version 5.10.2 — AireToken Fix <a class="header-anchor" href="#version-5-10-2-—-airetoken-fix" aria-label="Permalink to “Version 5.10.2 — AireToken Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 2, 2022</p></blockquote><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where AireForms could not mark a token as used in AireToken</li></ul><h2 id="version-5-10-1-—-annotated-images-mobile-improvements" tabindex="-1">Version 5.10.1 — Annotated Images &amp; Mobile Improvements <a class="header-anchor" href="#version-5-10-1-—-annotated-images-mobile-improvements" aria-label="Permalink to “Version 5.10.1 — Annotated Images &amp; Mobile Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 1, 2022</p></blockquote><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Numeric controls now display the full keyboard on mobile devices so users can enter negative values where required</li><li>The Extract Definition API now correctly returns a <code>404</code> when the requested form or building block does not exist</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the Annotated Image Upload control did not display an uploaded image when no annotations were made</li><li>Fixed an issue where hint text was not displayed for controls inside a single-iteration repeat on small-screen devices</li></ul><h2 id="version-5-10-0-—-extract-api-v2" tabindex="-1">Version 5.10.0 — Extract API V2 <a class="header-anchor" href="#version-5-10-0-—-extract-api-v2" aria-label="Permalink to “Version 5.10.0 — Extract API V2”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 1, 2022</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Introduced Extract API V2</li><li>Added the Extract Definition API</li><li>Added the <code>hideBanner=true</code> query parameter for removing the banner when requesting a PDF</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>The building block designer now supports the <code>round</code> function overload for specifying the number of decimal places</li><li>Numeric controls now display a numeric keyboard that supports decimal values</li><li>Improved rendering performance when editing large reference data sets</li><li>Improved schema generation</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where rotated uploaded images were not compressed correctly according to control settings</li><li>Fixed an issue where the Server Side Calculation control could lose its settings in the building block designer</li><li>Fixed an issue resetting a user&#39;s password in the designer</li><li>Fixed an issue where the Scribble control displayed <code>-</code> in read view despite containing a value</li><li>Prevented multiple versions of a form being created when the submit button was clicked multiple times</li></ul><h2 id="version-5-9-1-—-ios-decimal-keyboard" tabindex="-1">Version 5.9.1 — iOS Decimal Keyboard <a class="header-anchor" href="#version-5-9-1-—-ios-decimal-keyboard" aria-label="Permalink to “Version 5.9.1 — iOS Decimal Keyboard”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 17, 2022</p></blockquote><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the Decimal control did not provide a keyboard with a decimal point on iOS</li></ul><h2 id="version-5-9-0-—-operational-service-multi-tenant-definitions" tabindex="-1">Version 5.9.0 — Operational Service &amp; Multi-Tenant Definitions <a class="header-anchor" href="#version-5-9-0-—-operational-service-multi-tenant-definitions" aria-label="Permalink to “Version 5.9.0 — Operational Service &amp; Multi-Tenant Definitions”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 17, 2022</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added an operational service including health checks and configuration APIs</li><li>Added the ability to synchronise multiple form definitions</li><li>Added the ability to associate a tenant with a form definition directory</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Updated the form designer UI so delivery status and classification are always visible</li><li>Updated the automated XSD API to handle controls marked as omitted from submission</li><li>Optimised bundle size</li><li>Relaxed form key length validation to support longer form names</li><li>Improved usability of the Annotated Image control when the Enter key is pressed</li><li>Improved image sizing in view/read mode</li><li>Improved the read view of an empty Annotated Image control</li><li>Improved validation of required text fields containing only whitespace</li><li>Improved Slider control display on IE11</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed cross-building-block XPath validation in the form designer</li></ul><h3 id="🔧-maintenance" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Removed redundant use of <code>System.Drawing.Common</code></li><li>Added tests to validate behaviour for duplicate reference data codes</li></ul>`,90)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};